PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, login TEXT NOT NULL UNIQUE, senha_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS maquinas (id INTEGER PRIMARY KEY AUTOINCREMENT, patrimonio TEXT NOT NULL UNIQUE, tipo TEXT NOT NULL, modelo TEXT NOT NULL, ano INTEGER NOT NULL CHECK(ano>=1900), horimetro_atual REAL NOT NULL DEFAULT 0 CHECK(horimetro_atual>=0), horimetro_ultima_preventiva REAL NOT NULL DEFAULT 0 CHECK(horimetro_ultima_preventiva>=0), status TEXT NOT NULL DEFAULT 'Ativa' CHECK(status IN ('Ativa','Em manutenção')));
CREATE TABLE IF NOT EXISTS mecanicos (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, especialidade TEXT NOT NULL, ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN (0,1)));
CREATE TABLE IF NOT EXISTS pecas (id INTEGER PRIMARY KEY AUTOINCREMENT, codigo TEXT NOT NULL UNIQUE, nome TEXT NOT NULL, valor_unitario REAL NOT NULL CHECK(valor_unitario>=0), estoque INTEGER NOT NULL DEFAULT 0 CHECK(estoque>=0), estoque_minimo INTEGER NOT NULL DEFAULT 0 CHECK(estoque_minimo>=0));
CREATE TABLE IF NOT EXISTS ordens_servico (id INTEGER PRIMARY KEY AUTOINCREMENT, maquina_id INTEGER NOT NULL, mecanico_id INTEGER NOT NULL, tipo TEXT NOT NULL CHECK(tipo IN ('Preventiva','Corretiva')), descricao TEXT NOT NULL, data_abertura TEXT NOT NULL, data_conclusao TEXT, horas_trabalhadas REAL CHECK(horas_trabalhadas IS NULL OR horas_trabalhadas>0), status TEXT NOT NULL DEFAULT 'Aberta' CHECK(status IN ('Aberta','Em andamento','Concluída','Cancelada')), FOREIGN KEY(maquina_id) REFERENCES maquinas(id), FOREIGN KEY(mecanico_id) REFERENCES mecanicos(id));
CREATE TABLE IF NOT EXISTS itens_os (id INTEGER PRIMARY KEY AUTOINCREMENT, os_id INTEGER NOT NULL, peca_id INTEGER NOT NULL, quantidade INTEGER NOT NULL CHECK(quantidade>0), valor_unitario REAL NOT NULL CHECK(valor_unitario>=0), FOREIGN KEY(os_id) REFERENCES ordens_servico(id) ON DELETE CASCADE, FOREIGN KEY(peca_id) REFERENCES pecas(id));
